// frontend/src/pages/dashboard/DashboardPage.js
import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { projectsAPI, contractsAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { usePermissions, ROLE_COLORS, ROLE_ICONS } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import RoleBadge from '../../components/ui/RoleBadge';

const STATUS_CONFIG = {
  planifie:  { label:'Planifié',  color:'#6366F1', bg:'rgba(99,102,241,0.12)' },
  en_cours:  { label:'En cours',  color:'#F59E0B', bg:'rgba(245,158,11,0.12)' },
  suspendu:  { label:'Suspendu',  color:'#EF4444', bg:'rgba(239,68,68,0.12)'  },
  termine:   { label:'Terminé',   color:'#10B981', bg:'rgba(16,185,129,0.12)' },
};

function StatCard({ icon, label, value, color = '#F59E0B', sub, alert }) {
  return (
    <div className="card" style={{ padding:'20px 24px', borderLeft:`3px solid ${alert ? '#EF4444' : color}`, position:'relative' }}>
      {alert && <span style={{ position:'absolute', top:12, right:12, width:8, height:8, borderRadius:'50%', background:'#EF4444', boxShadow:'0 0 6px #EF4444' }} />}
      <div style={{ fontSize:28, marginBottom:10 }}>{icon}</div>
      <div style={{ fontSize:24, fontWeight:800, fontFamily:'var(--font-display)', color: alert ? '#EF4444' : color, marginBottom:4 }}>{value}</div>
      <div style={{ fontSize:12, color:'var(--gray-3)', textTransform:'uppercase', letterSpacing:'0.5px' }}>{label}</div>
      {sub && <div style={{ fontSize:12, color:'var(--gray-4)', marginTop:4 }}>{sub}</div>}
    </div>
  );
}

function ProjectCard({ project }) {
  const cfg = STATUS_CONFIG[project.status] || STATUS_CONFIG.planifie;
  const consumed = project.budget_consumed_pct;
  const isOver   = consumed > 100;
  const isDelayed = project.end_date && new Date(project.end_date) < new Date() && project.status !== 'termine';

  return (
    <Link to={`/projects/${project.id}`} style={{ textDecoration:'none' }}>
      <div className="card" style={{ cursor:'pointer', transition:'all 0.2s', position:'relative', overflow:'hidden' }}
        onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(245,158,11,0.35)'; e.currentTarget.style.transform = 'translateY(-2px)'; }}
        onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--dark-border)'; e.currentTarget.style.transform = 'none'; }}>
        <div style={{ position:'absolute', top:0, left:0, right:0, height:2, background: cfg.color, opacity:0.6 }} />
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:12 }}>
          <h3 style={{ fontFamily:'var(--font-display)', fontSize:15, fontWeight:700, margin:0, flex:1, marginRight:12, lineHeight:1.3 }}>
            {project.name}
          </h3>
          <span style={{ padding:'3px 10px', borderRadius:100, fontSize:11, fontWeight:600, color:cfg.color, background:cfg.bg, whiteSpace:'nowrap', flexShrink:0 }}>
            {cfg.label}
          </span>
        </div>
        {project.location && <p style={{ fontSize:12, color:'var(--gray-3)', margin:'0 0 12px' }}>📍 {project.location}</p>}
        <div style={{ display:'flex', gap:16, borderTop:'1px solid var(--dark-border)', paddingTop:12, fontSize:12 }}>
          <span style={{ color:'var(--gray-3)' }}>📄 {project.contracts_count ?? 0} contrat(s)</span>
          {project.progress_pct != null && <span style={{ color:'var(--gray-3)' }}>⚡ {project.progress_pct}% avancement</span>}
          {isOver   && <span style={{ color:'#EF4444', fontWeight:600 }}>⚠️ Dépassement budget</span>}
          {isDelayed && <span style={{ color:'#EF4444', fontWeight:600 }}>🕐 En retard</span>}
        </div>
      </div>
    </Link>
  );
}

// ── Role-specific quick actions ───────────────────────────────────────────

function QuickActions() {
  const { role, can, canWrite } = usePermissions();

  const actions = [
    canWrite('journal')    && { to:'/projects', label:'+ Nouveau rapport', icon:'📓', color:'#F59E0B' },
    canWrite('config')     && { to:'/projects/new', label:'+ Nouveau projet', icon:'🏗️', color:'#6366F1' },
    can('budget')          && { to:'/budget',   label:'Suivi budget',      icon:'💰', color:'#10B981' },
    can('qhse')            && { to:'/qhse',     label:'Checklist QHSE',   icon:'🛡️', color:'#EF4444' },
    can('documents')       && { to:'/documents',label:'Documents',         icon:'📁', color:'#06B6D4' },
    can('reports')         && { to:'/reports',  label:'Rapports',          icon:'📈', color:'#8B5CF6' },
    true                   && { to:'/contracts/upload', label:'Analyser contrat', icon:'📄', color:'#F59E0B' },
  ].filter(Boolean);

  return (
    <div style={{ display:'flex', gap:10, flexWrap:'wrap' }}>
      {actions.map((a, i) => (
        <Link key={i} to={a.to} style={{
          display:'flex', alignItems:'center', gap:8,
          padding:'10px 18px', borderRadius:8,
          border:`1px solid ${a.color}44`,
          background:`${a.color}11`,
          color: a.color,
          textDecoration:'none', fontSize:13, fontWeight:600,
          fontFamily:'Barlow Condensed', letterSpacing:0.3,
          transition:'all 0.15s',
        }}
        onMouseEnter={e => { e.currentTarget.style.background = `${a.color}22`; }}
        onMouseLeave={e => { e.currentTarget.style.background = `${a.color}11`; }}>
          <span>{a.icon}</span> {a.label}
        </Link>
      ))}
    </div>
  );
}

// ── Main Dashboard ────────────────────────────────────────────────────────

export default function DashboardPage() {
  const { user } = useAuth();
  const { role, roleColor, roleIcon, can } = usePermissions();
  const [projects, setProjects]   = useState([]);
  const [contracts, setContracts] = useState([]);
  const [loading, setLoading]     = useState(true);

  useEffect(() => {
    Promise.all([
      projectsAPI.list().catch(() => ({ data:[] })),
      contractsAPI.list().catch(() => ({ data:[] })),
    ]).then(([p, c]) => {
      setProjects(p.data);
      setContracts(c.data);
    }).finally(() => setLoading(false));
  }, []);

  const stats = {
    total:       projects.length,
    en_cours:    projects.filter(p => p.status === 'en_cours').length,
    termine:     projects.filter(p => p.status === 'termine').length,
    overBudget:  projects.filter(p => p.budget_consumed_pct > 100).length,
    delayed:     projects.filter(p => p.end_date && new Date(p.end_date) < new Date() && p.status !== 'termine').length,
    totalBudget: projects.reduce((a, p) => a + (parseFloat(p.budget) || 0), 0),
    totalExp:    projects.reduce((a, p) => a + (parseFloat(p.actual_expenses) || 0), 0),
    contracts:   contracts.length,
  };

  const fmtFCFA = (n) => {
    if (n >= 1_000_000_000) return `${(n/1_000_000_000).toFixed(2)} Mrd FCFA`;
    if (n >= 1_000_000)     return `${(n/1_000_000).toFixed(1)} M FCFA`;
    return `${n.toLocaleString('fr-FR')} FCFA`;
  };

  return (
    <AppLayout>
      <div style={{ padding:'36px 40px' }} className="animate-fade-in">

        {/* Header */}
        <div style={{ marginBottom:32 }}>
          <p style={{ color:'#6B7280', fontSize:13, margin:'0 0 4px', fontFamily:'Barlow Condensed', letterSpacing:0.5 }}>
            {new Date().toLocaleDateString('fr-FR', { weekday:'long', year:'numeric', month:'long', day:'numeric' })}
          </p>
          <div style={{ display:'flex', alignItems:'center', gap:16, flexWrap:'wrap' }}>
            <h1 style={{ fontFamily:'Bebas Neue', fontSize:38, color:'#fff', letterSpacing:1, margin:0 }}>
              Bonjour, <span style={{ color:'#F59E0B' }}>{user?.full_name?.split(' ')[0]}</span> 👋
            </h1>
            <RoleBadge role={role} />
          </div>
          <p style={{ color:'#6B7280', fontSize:14, margin:'4px 0 0' }}>{user?.company_name}</p>
        </div>

        {/* Stats — filtered by role */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(180px, 1fr))', gap:16, marginBottom:36 }}>
          <StatCard icon="🏗️" label="Total projets"  value={stats.total}   color="#6366F1" />
          <StatCard icon="⚡"  label="En cours"       value={stats.en_cours} color="#F59E0B" />
          <StatCard icon="✅"  label="Terminés"       value={stats.termine}  color="#10B981" />
          {can('budget') && (
            <StatCard icon="💰" label="Budget total"   value={fmtFCFA(stats.totalBudget)} color="#10B981" />
          )}
          {can('budget') && (
            <StatCard icon="💸" label="Dépenses"       value={fmtFCFA(stats.totalExp)} color="#F59E0B"
              alert={stats.overBudget > 0}
              sub={stats.overBudget > 0 ? `⚠️ ${stats.overBudget} projet(s) en dépassement` : undefined} />
          )}
          {stats.delayed > 0 && (
            <StatCard icon="🕐" label="En retard"      value={stats.delayed} color="#EF4444" alert />
          )}
          <StatCard icon="📄" label="Contrats IA"    value={stats.contracts} color="#06B6D4" />
        </div>

        {/* Quick actions */}
        <div style={{ marginBottom:36 }}>
          <h2 style={{ fontFamily:'Bebas Neue', fontSize:22, color:'#fff', letterSpacing:1, marginBottom:14 }}>Actions rapides</h2>
          <QuickActions />
        </div>

        {/* Recent projects */}
        <div>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:18 }}>
            <h2 style={{ fontFamily:'Bebas Neue', fontSize:22, color:'#fff', letterSpacing:1, margin:0 }}>
              {role === 'client' ? 'Mes projets' : 'Projets récents'}
            </h2>
            <Link to="/projects" style={{ color:'#F59E0B', fontSize:13, textDecoration:'none', fontFamily:'Barlow Condensed', fontWeight:600, letterSpacing:0.3 }}>
              Voir tous →
            </Link>
          </div>

          {loading ? (
            <div style={{ textAlign:'center', padding:'48px 0' }}>
              <div style={{ width:32, height:32, border:'3px solid #F59E0B', borderTopColor:'transparent', borderRadius:'50%', animation:'spin 1s linear infinite', margin:'0 auto 12px' }} />
              <p style={{ color:'#6B7280' }}>Chargement...</p>
            </div>
          ) : projects.length === 0 ? (
            <div className="card" style={{ textAlign:'center', padding:'56px 24px' }}>
              <div style={{ fontSize:52, marginBottom:16 }}>🏗️</div>
              <h3 style={{ fontFamily:'Bebas Neue', fontSize:22, color:'#fff', marginBottom:8 }}>Aucun projet</h3>
              <p style={{ color:'#6B7280', marginBottom:20 }}>
                {can('config') ? 'Créez votre premier projet.' : 'Vous n\'avez pas encore été assigné à un projet.'}
              </p>
              {can('config') && (
                <Link to="/projects/new" style={{ padding:'10px 24px', borderRadius:8, background:'#F59E0B', color:'#0D0D1A', fontWeight:700, textDecoration:'none', fontSize:14 }}>
                  + Nouveau projet
                </Link>
              )}
            </div>
          ) : (
            <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill, minmax(300px, 1fr))', gap:16 }}>
              {projects.slice(0, role === 'client' ? 3 : 6).map(p => (
                <ProjectCard key={p.id} project={p} />
              ))}
            </div>
          )}
        </div>

        {/* Client-specific: read-only notice */}
        {role === 'client' && (
          <div style={{ marginTop:28, padding:'14px 20px', background:'rgba(59,130,246,0.08)', border:'1px solid rgba(59,130,246,0.2)', borderRadius:10, display:'flex', alignItems:'center', gap:12 }}>
            <span style={{ fontSize:20 }}>ℹ️</span>
            <p style={{ color:'#93C5FD', fontSize:13, margin:0 }}>
              Vous avez accès en lecture seule aux projets qui vous ont été partagés. Pour toute question, contactez votre chef de projet.
            </p>
          </div>
        )}

      </div>
    </AppLayout>
  );
}
